#!/usr/bin/env bash
set -euo pipefail
echo "Aplic patch-ul v12: fereastra tolerata la intarzieri GitHub Actions + protectie duplicate"

mkdir -p .github/workflows
base64 -d > .github/workflows/daily-report.yml << 'B64_YML'

B64_YML

python3 -c "import yaml; yaml.safe_load(open(\".github/workflows/daily-report.yml\"))" && echo "YAML VALID" || echo "modulul yaml lipseste local, dar GitHub il va valida la push"
echo "Gata. Verifica cu: git status"
